import type { Meta, StoryObj } from "@storybook/vue3";
import { h, ref } from "vue";
import { KozmosNumberInput, KozmosThemeProvider } from "../../index";

/**
 * Vue's NumberInput: the stories React's has, with the same names and
 * args, each drawn as React's story draws it, inside the
 * KozmosThemeProvider the Storybook's decorator gives every story.
 * test/parity/number-input.parity.spec.ts draws each in both and holds
 * Vue's render to React's. Generated by `port NumberInput`; the stories
 * React draws by hand written by hand.
 */
type Args = Record<string, unknown>;

/** React's args as Vue's props: a controlled `value` is `v-model`'s. */
const vueArgs = (args: Args) => {
  const { value, ...rest } = args;
  return value === undefined ? rest : { ...rest, modelValue: value };
};

const meta: Meta<Args> = {
  title: "Vue/Core/Inputs/NumberInput",
  component: KozmosNumberInput,
  parameters: { layout: "centered" },
  argTypes: {
    status: {
      control: "select",
      options: ["default", "error", "warning", "success"],
    },
    showSteppers: { control: "boolean" },
  },
  render: (args) => ({
    setup: () => () => h(KozmosNumberInput, vueArgs(args)),
  }),
};

export default meta;
type Story = StoryObj<Args>;

/** The field in a 320 box, React's props first and the story's args over them. */
const boxed = (props: Args) => (args: Args) => ({
  setup: () => () =>
    h("div", { class: "w-80" }, [
      h(KozmosNumberInput, { ...props, ...vueArgs(args) }),
    ]),
});

export const Default: Story = {
  args: {
    defaultValue: 3,
    label: "Floors",
    min: 0,
    step: 1,
  },
  render: boxed({}),
};

export const WithHelperText: Story = {
  render: boxed({
    defaultValue: 12,
    helperText: "Use a whole number.",
    label: "Capacity",
    min: 0,
  }),
};

export const ValidationStates: Story = {
  render: () => ({
    setup: () => () =>
      h("div", { class: "grid w-80 gap-4" }, [
        h(KozmosNumberInput, {
          defaultValue: 8,
          helperText: "Default numeric field.",
          label: "Default",
        }),
        h(KozmosNumberInput, {
          defaultValue: 2,
          helperText: "Check the selected value.",
          label: "Warning",
          status: "warning",
        }),
        h(KozmosNumberInput, {
          defaultValue: 16,
          helperText: "Value is available.",
          label: "Success",
          status: "success",
        }),
        h(KozmosNumberInput, {
          error: "Enter a value between 1 and 10.",
          label: "Error",
          min: 1,
          max: 10,
        }),
      ]),
  }),
};

export const WithoutSteppers: Story = {
  render: boxed({ defaultValue: 24, label: "Radius", showSteppers: false }),
};

// A unit inside the field after the value (GAP-098): never part of the
// value, and read after it by its spoken name.
export const WithUnit: Story = {
  render: () => ({
    setup: () => () =>
      h("div", { class: "grid w-80 gap-4" }, [
        h(KozmosNumberInput, {
          defaultValue: 15,
          label: "Width",
          min: 0,
          unit: "m",
          unitLabel: "metres",
        }),
        h(KozmosNumberInput, {
          defaultValue: 20,
          label: "Height",
          min: 0,
          showSteppers: false,
          unit: "m",
          unitLabel: "metres",
        }),
      ]),
  }),
};

export const WithUnitRightToLeft: Story = {
  render: (_args, { globals }) => ({
    setup: () => () =>
      h(
        KozmosThemeProvider,
        { dir: "rtl", theme: globals?.theme === "dark" ? "dark" : "light" },
        () => [
          h("div", { class: "grid gap-4", style: { width: "220px" } }, [
            h(KozmosNumberInput, {
              label: "Width",
              defaultValue: 15,
              unit: "m",
            }),
            h(KozmosNumberInput, {
              label: "Height",
              defaultValue: 20,
              showSteppers: false,
              unit: "m",
            }),
          ]),
        ],
      ),
  }),
};

export const RightToLeft: Story = {
  render: (_args, { globals }) => ({
    setup: () => () =>
      h(
        KozmosThemeProvider,
        { dir: "rtl", theme: globals?.theme === "dark" ? "dark" : "light" },
        () => [
          h("div", { style: { width: "220px" } }, [
            h(KozmosNumberInput, {
              label: "Floors",
              defaultValue: 3,
              status: "warning",
              helperText: "Narrow RTL field",
            }),
          ]),
        ],
      ),
  }),
};

export const ReadOnly: Story = {
  args: { label: "Floors", value: 3, readOnly: true },
};

/**
 * GAP-153: a value the selected features do not share. Mixed, the field is
 * empty with "Multiple values" and its steppers disabled; a typed number
 * edits it, and "Reset to multiple values" takes it back.
 */
export const MixedValue: Story = {
  render: () => ({
    setup: () => {
      const field = (label: string, edited?: number) => {
        const edit = ref<number | null | undefined>(edited);
        return () =>
          h(KozmosNumberInput, {
            label,
            min: 0,
            mixed: edit.value === undefined,
            modelValue: edit.value ?? "",
            "onUpdate:modelValue": (next: number | null) => (edit.value = next),
            onResetMixed: () => (edit.value = undefined),
          });
      };
      const height = field("Height (m)");
      const capacity = field("Capacity", 12);
      return () =>
        h("div", { class: "grid w-80 gap-4" }, [height(), capacity()]);
    },
  }),
};
